                      CPU {host.cpu_usage_pct.toFixed(1)}%
                    </span>
                  )}
                  {host.mem_usage_pct != null && (
                    <span className={`px-2 py-0.5 rounded-full text-xs font-medium border
                      ${host.mem_usage_pct >= 90
                        ? 'bg-red-500/15 text-red-400 border-red-500/30'
