                {saving ? <><div className="w-4 h-4 border-2 border-white/40 border-t-white rounded-full animate-spin" />Kaydediliyor...</> : 'Ekle'}
              </button>
            </div>
          )}

        </div>
      </div>
    </div>
  )
}

