const useSyncProgress = (repoId: number, active: boolean) => {
  const [progress, setProgress] = useState<SyncProgress | null>(null)

  useEffect(() => {
    if (!active) { setProgress(null); return }
    let cancelled = false

    const fetch_ = async () => {
      try {
        const r = await fetch(`${API}/${repoId}/progress`)
        if (r.ok && !cancelled) setProgress(await r.json())
      } catch { /* ignore */ }
